using System;
using System.Collections.Generic;
using System.Linq;

class Program {
    static void Main() {
        List<int> numeros = new List<int> { 1, 2, 3, 4, 5, 6 };

        var pares = numeros.Where(n => n % 2 == 0);

        foreach (var n in pares) {
            Console.WriteLine(n);
        }
    }
}
